local function CurrentPeer(self, peer)
    if not peer then return false end
    if peer.gameAccountID then
        if not BattleNetConnected(self) then return false end
        local account = Read(C_BattleNet and C_BattleNet.GetFriendAccountInfo, peer.friendIndex)
        if not FriendAccount(account) then return false end
        local game
        if peer.accountIndex then
            game = Read(C_BattleNet and C_BattleNet.GetFriendGameAccountInfo, peer.friendIndex, peer.accountIndex)
        else
            game = account.gameAccountInfo
        end
        return GameKey(self, game) == peer.key and game.gameAccountID == peer.gameAccountID
    end
    local info = Read(C_FriendList and C_FriendList.GetFriendInfoByIndex, peer.friendIndex)
    return Table(info)
        and Public(info.connected)
        and info.connected == true
        and Public(info.name)
        and self:PlayerKey(info.name) == peer.key
end--[[APR_DIAG]]
