function Finder:RefreshFriendPeers(force)
    local bnetReady = BattleNetConnected(self)
    if self.friendBattleNetReady ~= bnetReady then self.friendPeersDirty = true end
    if self.friendPeers and not force and not self.friendPeersDirty then return self.friendPeers end
    self.friendBattleNetReady = bnetReady
    self.friendPeersDirty = nil
    local peers, byGame, order = {}, {}, {}
    local function Add(peer)
        if not peer.key or peer.key == self.playerKey then return end
        local old = peers[peer.key]
        if not old then
            if #order >= PEER_LIMIT then return end
            order[#order + 1] = peer.key
        elseif old.gameAccountID then
            -- One character can be present in both social lists or on multiple account records.
            return
        end
        peers[peer.key] = peer
        if peer.gameAccountID then byGame[peer.gameAccountID] = peer end
    end--[[APR_DIAG]]
    Add = APRTrace("APR-Core/features/group/PartyFinderFriends.lua:99:Add#12", Add)--[[/APR_DIAG]]
    local count = Read(C_FriendList and C_FriendList.GetNumFriends)
    if PositiveInteger(count) then
        for index = 1, math.min(ROSTER_LIMIT, count) do
            local info = Read(C_FriendList and C_FriendList.GetFriendInfoByIndex, index)
            if Table(info) and Public(info.connected) and info.connected == true and Public(info.name) then
                Add({ key = self:PlayerKey(info.name), channel = "WHISPER", friendIndex = index })
            end
        end
    end
    count = bnetReady and BattleNetSender() and Read(BNGetNumFriends)
    if PositiveInteger(count) then
        for index = 1, math.min(ROSTER_LIMIT, count) do
            local account = Read(C_BattleNet and C_BattleNet.GetFriendAccountInfo, index)
            if FriendAccount(account) then
                local games = Read(C_BattleNet and C_BattleNet.GetFriendNumGameAccounts, index)
                if PositiveInteger(games) then
                    for gameIndex = 1, math.min(ACCOUNT_LIMIT, games) do
                        local game = Read(C_BattleNet.GetFriendGameAccountInfo, index, gameIndex)
                        local key = GameKey(self, game)
                        if key then
                            Add({
                                key = key,
                                channel = "BNET",
                                gameAccountID = game.gameAccountID,
                                friendIndex = index,
                                accountIndex = gameIndex,
                            })
                        end
                    end
                elseif type(C_BattleNet.GetFriendNumGameAccounts) ~= "function" then
                    local game = account.gameAccountInfo
                    local key = GameKey(self, game)
                    if key then
                        Add({
                            key = key,
                            channel = "BNET",
                            gameAccountID = game.gameAccountID,
                            friendIndex = index,
                        })
                    end
                end
            end
        end
    end
    table.sort(order)
    self.friendPeers, self.friendBattleNetPeers, self.friendPeerOrder = peers, byGame, order
    for key, id in pairs(self.friendRoutes or {}) do
        if not peers[key] or peers[key].gameAccountID ~= id then self.friendRoutes[key] = nil end
    end
    local changed
    for key, candidate in pairs(self.candidates or {}) do
        if candidate.gameAccountID and (not peers[key] or peers[key].gameAccountID ~= candidate.gameAccountID) then
            self.candidates[key], self.candidatesDirty, changed = nil, true, true
        end
    end
    if changed then self:Notify() end
    return peers
end--[[APR_DIAG]]
