        local ok, allowed = --[[APR_DIAG]]
            APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](entry.guard)
        if not ok or not Public(allowed) or allowed ~= true then return false end
    end
